{
  "status": "SUPPORTED",
  "task_summary": "Provide two refreshment sets on surfaces and move the remote to an accessible central spot.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_set",
        "entity_kind": "OBJECT",
        "function": "holds food or drink for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "napkin"],
        "required_properties": ["is_food_or_drink_container"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "operates the television",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote_control"],
        "required_properties": ["is_remote"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "flat horizontal area to hold items",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "side_table", "coffee_table"],
        "required_properties": ["is_horizontal", "is_stable"]
      },
      {
        "id": "accessible_zone",
        "entity_kind": "REGION",
        "function": "central area reachable by both seated people",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["floor", "ottoman", "low_table"],
        "required_properties": ["is_central", "is_low"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "placed_on",
        "participant_roles": ["refreshment_set", "surface"],
        "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "located_in",
        "participant_roles": ["entertainment_control", "accessible_zone"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "set_refreshments",
        "operation": "place",
        "participant_roles": ["refreshment_set", "surface"],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "move_to",
        "participant_roles": ["entertainment_control", "accessible_zone"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_set": [
        {"label": "coffee_table_items", "visual_description": "red cup and white plate on the central coffee table"},
        {"label": "desk_items", "visual_description": "red cup, white plate, and black remote on the desk in the foreground"}
      ],
      "entertainment_control": [
        {"label": "desk_remote", "visual_description": "black rectangular object on the desk"}
      ],
      "surface": [
        {"label": "coffee_table", "visual_description": "central rectangular table"},
        {"label": "left_side_table", "visual_description": "small wooden table next to left chair"},
        {"label": "right_side_table", "visual_description": "small wooden table next to right chair"},
        {"label": "desk", "visual_description": "large wooden table in the foreground"}
      ],
      "accessible_zone": [
        {"label": "floor_between_chairs", "visual_description": "open floor space between the two armchairs"}
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
